    dark: BTreeMap<String, (u8, TokenValue)>,
    /// `META::SET_COLOR_SCHEME` override (`None` = platform).
    scheme_override: Option<Scheme>,
}

impl Tokens {
    fn set(&mut self, path: &str, value_type: u8, value: TokenValue) {
        if let Some(bare) = path.strip_prefix("dark.") {
            self.dark.insert(bare.to_string(), (value_type, value));
        } else {
            self.base.insert(path.to_string(), (value_type, value));
        }
    }

    /// `META::RESET_THEME`: drop every application override (base + dark).
    fn reset(&mut self) {
        self.base.clear();
        self.dark.clear();
    }

    /// The scheme selector contributions. Base rules are `:root`; dark rules
    /// apply when the platform is dark (and no override is active) **and**
    /// unconditionally under `[data-pathland-scheme="dark"]`. A forced light
    /// scheme suppresses the media query via `:not([data-pathland-scheme])`.
    fn dark_rule(&self, selector: &str, path: &str, vt: u8, value: &TokenValue) -> String {
        format!(
            "{selector}{{{}:{};}}",
            token_to_css_var(path),
            token_css_value(path, vt, value)
        )
    }

